def generate(seed):
    r = random.Random(seed)
    n = r.choice([6, 7, 8])

    def rec(i, p, used, d1, d2):
        if i == n:
            return p
        opts = list(range(n)); r.shuffle(opts)
        for v in opts:
            if v in used or v - i in d1 or v + i in d2:
                continue
            res = rec(i + 1, p + [v], used | {v}, d1 | {v - i}, d2 | {v + i})
            if res:
                return res
        return None

    p = rec(0, [], set(), set(), set())
    g = [['.'] * n for _ in range(n)]
    free = [(y, x) for y in range(n) for x in range(n) if p[x] != y]
    r.shuffle(free)
    for y, x in free[:r.randrange(3, 3 * n)]:
        g[y][x] = 'X'
    return '\n'.join(''.join(row) for row in g)

