def solve(clue):
    g = clue.split()
    n = len(g)

    def rec(i, p, used, d1, d2):
        if i == n:
            return p
        for v in range(n):
            if v in used or v - i in d1 or v + i in d2 or g[v][i] != '.':
                continue
            res = rec(i + 1, p + [v], used | {v}, d1 | {v - i}, d2 | {v + i})
            if res:
                return res
        return None

    p = rec(0, [], set(), set(), set())
    return ''.join(str(v) for v in p) if p else ''

